import { loadFont as loadBricolage } from "@remotion/google-fonts/BricolageGrotesque";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import React, { forwardRef, useEffect, useImperativeHandle, useLayoutEffect, useMemo, useRef, type ComponentProps } from "react";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

const bricolage = loadBricolage("normal", {
  weights: ["500"],
  subsets: ["latin"],
});
const geist = loadGeist("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

/**
 * Beat sheet (30fps, speed 1, three items, 165 frames):
 * 6–40     "Fast." rises out of a mask at hero size, its line follows; a row
 *          of progress ticks under it fills for the current item.
 * 40–74    it leaves upward as "Composable." rises into the same spot.
 * 74–104   "Open source." rises and holds.
 * 104–132  resolve: the last title shrinks and travels into its column,
 *          the earlier titles rise back into theirs, the ticks stretch into
 *          the column rules, descriptions settle under each.
 * 132–165  poster hold.
 * The per-item slot stretches or shrinks with `durationInFrames`.
 */

interface FeatureTrioItem {
  title: string;
  description: string;
}

interface FeatureTrioProps {
  /** 2–4 short benefits. */
  items?: FeatureTrioItem[];
  /** Frames the finished row holds at the end; each item's slot shrinks to make room. */
  hold?: number;
  accent?: string;
  /** Text color of the titles; overrides the theme. */
  ink?: string;
  /** Stage fill. "transparent" drops the stage and its glow. */
  background?: string;
  /** Typeface for the titles. Load it yourself; Bricolage Grotesque by default. */
  fontFamily?: string;
  /** Size of the copy and rules, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

/** gradients.sh "grain": bg #070505, [#ffd8b4, #e0703b, #8a2c1d, #2b1015]. */
const GRAIN = ["#ffd8b4", "#e0703b", "#8a2c1d", "#2b1015"] as const;
/** gradients.sh "smear" (light): bg #efe8dc, [#f2552c, #f7b23b, #e889b5, #2f6b3f]. */
const SMEAR = ["#f2552c", "#f7b23b", "#e889b5", "#2f6b3f"] as const;

const PALETTES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F4F3F0",
    muted: "#8E8D94",
    track: "rgba(255,255,255,0.14)",
    rule: "rgba(255,255,255,0.22)",
    glow: [GRAIN[0], GRAIN[1], GRAIN[2]],
    glowAlpha: [0.36, 0.4, 0.42],
  },
  light: {
    bg: "#F5F4F0",
    fg: "#111113",
    muted: "#6E6C67",
    track: "rgba(17,17,19,0.12)",
    rule: "rgba(17,17,19,0.2)",
    glow: [SMEAR[1], SMEAR[0], SMEAR[2]],
    glowAlpha: [0.22, 0.16, 0.18],
  },
} as const;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IN = Easing.bezier(0.6, 0, 0.9, 0.5);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

/** Bricolage Grotesque 500 advances (per 1000 em), ASCII 32–126. */
const BRICOLAGE_500 = [
  246, 266, 317, 612, 630, 947, 756, 158, 305, 290, 395, 516, 165, 339, 196,
  353, 656, 320, 583, 595, 595, 599, 646, 493, 645, 640, 207, 187, 516, 516,
  516, 413, 952, 671, 666, 670, 691, 599, 578, 706, 708, 274, 357, 666, 508,
  908, 746, 716, 629, 719, 660, 641, 553, 719, 657, 957, 652, 600, 560, 315,
  341, 300, 546, 578, 283, 567, 618, 555, 617, 570, 380, 588, 608, 259, 266,
  561, 257, 912, 608, 604, 618, 617, 411, 535, 380, 599, 546, 827, 534, 591,
  500, 353, 259, 331, 516,
];
const TRACK = -0.04;

function titleEm(text: string) {
  let w = 0;
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    w += c >= 32 && c <= 126 ? BRICOLAGE_500[c - 32] : 620;
  }
  return w / 1000 + TRACK * [...text].length;
}

const DEFAULT_ITEMS: FeatureTrioItem[] = [
  { title: "Fast.", description: "Drop in a scene and render it in minutes." },
  {
    title: "Composable.",
    description: "Every piece is a React component you can remix.",
  },
  {
    title: "Open source.",
    description: "MIT licensed. The code lands in your repo.",
  },
];

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function FeatureTrioBase({
  items = DEFAULT_ITEMS,
  hold = 36,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = bricolage.fontFamily,
  scale = 1,
  delay = 0,
  speed = 1,
  theme = "dark",
}: FeatureTrioProps) {
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const p = PALETTES[theme];
  const fg = ink ?? p.fg;
  const list = items.slice(0, 4);
  const n = list.length;
  const portrait = height > width * 1.1;
  const s = portrait
    ? (width / 1280) * 1.5
    : Math.min(width / 1280, height / 720);

  // ---- timing ----------------------------------------------------------------
  const START = 6;
  const RESOLVE = 24;
  const total = durationInFrames * speed;
  const slot = Math.max(
    22,
    Math.min(40, (total - START - RESOLVE - hold + 4) / Math.max(1, n)),
  );
  const at = (i: number) => START + i * slot;
  const r0 = at(n - 1) + slot - 4;
  const resolve = interpolate(frame, [r0, r0 + RESOLVE], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  // ---- geometry ----------------------------------------------------------------
  const maxEm = Math.max(...list.map((it) => titleEm(it.title)), 1);
  const heroFs = Math.min((portrait ? 150 : 172) * s, (width * 0.84) / maxEm);
  const heroY = height * (portrait ? 0.46 : 0.45);
  const heroDescFs = (portrait ? 34 : 28) * s;
  const heroDescTop = heroY + heroFs * 0.52 + 18 * s;
  // progress ticks sit above the hero title, so on the way to becoming the
  // column rules they never cross a line of text
  const ticksY = heroY - heroFs * 0.62 - (portrait ? 48 : 34) * s;
  const tickW = 40 * s;
  const tickGap = 8 * s;
  const ticksW = n * tickW + (n - 1) * tickGap;

  // final layout: a row (landscape) or a stack (portrait)
  const rowW = Math.min(width * 0.88, 1180 * s);
  const colW = portrait ? width * 0.84 : rowW / n;
  const gutter = (portrait ? 0 : 26) * s;
  const rowFs = portrait
    ? Math.min(84 * s, (colW * 0.92) / maxEm)
    : Math.min(60 * s, ((colW - gutter * 2) * 0.94) / maxEm);
  const rowDescFs = (portrait ? 28 : 19) * s;
  const ruleToTitle = rowFs * 0.5 + 30 * s;
  const titleToDesc = rowFs * 0.52 + 12 * s;
  const blockH = ruleToTitle + titleToDesc + rowDescFs * 1.45 * 2;
  const stackGap = 64 * s;
  const col = (i: number) => {
    if (portrait) {
      const groupH = n * blockH + (n - 1) * stackGap;
      const top = height / 2 - groupH / 2 + i * (blockH + stackGap);
      return { x: width / 2, ruleY: top, w: colW * 0.4 };
    }
    const groupH = blockH;
    return {
      x: width / 2 - rowW / 2 + colW * (i + 0.5),
      ruleY: height / 2 - groupH / 2,
      w: colW - gutter * 2,
    };
  };

  const transparent = background === "transparent";

  // the glow breathes with each new item and widens into a band for the row
  const beat = list.reduce(
    (acc, _, i) =>
      acc +
      interpolate(
        frame,
        [at(i), at(i) + 10, at(i) + slot],
        [0, 1, 0.35],
        CLAMP,
      ) *
        (i === n - 1
          ? 1
          : interpolate(frame, [at(i + 1), at(i + 1) + 6], [1, 0], CLAMP)),
    0,
  );
  const glowIn = interpolate(frame, [0, 24], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const glowW = interpolate(resolve, [0, 1], [46, 95]);
  const glowH = interpolate(resolve, [0, 1], [58, 44]);
  const glowY = interpolate(resolve, [0, 1], [104, 112]);
  const glowLift = 0.75 + Math.min(1, beat) * 0.25;

  return (
    <AbsoluteFill
      style={{
        background: transparent ? "transparent" : (background ?? p.bg),
        overflow: "hidden",
      }}
    >
      {!transparent && background === undefined ? (
        <div
          style={{
            position: "absolute",
            inset: 0,
            opacity: glowIn * glowLift,
            background: [
              `radial-gradient(${glowW * 0.6}% ${glowH * 0.6}% at 50% ${glowY}%, color-mix(in oklab, ${p.glow[0]} ${p.glowAlpha[0] * 100}%, transparent) 0%, transparent 70%)`,
              `radial-gradient(${glowW * 0.85}% ${glowH * 0.85}% at 50% ${glowY}%, color-mix(in oklab, ${p.glow[1]} ${p.glowAlpha[1] * 100}%, transparent) 0%, transparent 70%)`,
              `radial-gradient(${glowW * 1.1}% ${glowH * 1.1}% at 50% ${glowY + 4}%, color-mix(in oklab, ${p.glow[2]} ${p.glowAlpha[2] * 100}%, transparent) 0%, transparent 72%)`,
            ].join(", "),
          }}
        />
      ) : null}

      <ScaleLayer scale={scale}>
        {/* ticks → column rules */}
        {list.map((it, i) => {
          const c = col(i);
          const tickX =
            width / 2 - ticksW / 2 + i * (tickW + tickGap) + tickW / 2;
          const x = interpolate(resolve, [0, 1], [tickX, c.x]);
          const y = interpolate(resolve, [0, 1], [ticksY, c.ruleY]);
          const w = interpolate(resolve, [0, 1], [tickW, c.w]);
          const th = interpolate(resolve, [0, 1], [3, 1.5]) * s;
          const fill =
            i === n - 1
              ? interpolate(frame, [at(i), at(i) + slot - 6], [0, 1], CLAMP)
              : interpolate(frame, [at(i), at(i + 1)], [0, 1], CLAMP);
          const tickIn = interpolate(frame, [0, 14], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          // the accent hands over to a neutral rule once the row stands
          const accentShare = 1 - resolve;
          return (
            <div
              key={`${it.title}-rule`}
              style={{
                position: "absolute",
                left: x - w / 2,
                top: y - th / 2,
                width: w,
                height: th,
                borderRadius: th,
                background: resolve > 0 ? p.rule : p.track,
                overflow: "hidden",
                opacity: tickIn,
                transform: `scaleX(${0.4 + tickIn * 0.6})`,
              }}
            >
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  bottom: 0,
                  width: `${fill * 100}%`,
                  background: accent,
                  opacity: accentShare,
                }}
              />
            </div>
          );
        })}

        {list.map((it, i) => {
          const last = i === n - 1;
          const c = col(i);
          const rowTitleY = c.ruleY + ruleToTitle;
          const rowDescTop = c.ruleY + ruleToTitle + titleToDesc;

          // solo: rise in, hold, leave upward (except the last)
          const rise = interpolate(frame, [at(i), at(i) + 14], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          const leave = last
            ? 0
            : interpolate(frame, [at(i + 1) - 8, at(i + 1) + 2], [0, 1], {
                ...CLAMP,
                easing: EASE_IN,
              });
          const descIn = interpolate(frame, [at(i) + 5, at(i) + 19], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          // row: earlier titles come back into their columns
          const back = interpolate(
            frame,
            [r0 + 15 + i * 3, r0 + 31 + i * 3],
            [0, 1],
            { ...CLAMP, easing: EASE_OUT },
          );
          const rowDescIn = interpolate(
            frame,
            [r0 + 20 + i * 3, r0 + 36 + i * 3],
            [0, 1],
            { ...CLAMP, easing: EASE_OUT },
          );

          const titleStyle = {
            fontFamily,
            fontWeight: 500,
            letterSpacing: `${TRACK}em`,
            lineHeight: 1,
            color: fg,
            whiteSpace: "nowrap" as const,
          };

          // hero copy (and, for the last item, the copy that travels)
          const heroX = last
            ? interpolate(resolve, [0, 1], [width / 2, c.x])
            : width / 2;
          const heroYNow = last
            ? interpolate(resolve, [0, 1], [heroY, rowTitleY])
            : heroY;
          const heroFsNow = last
            ? interpolate(resolve, [0, 1], [heroFs, rowFs])
            : heroFs;
          const soloY = (1 - rise) * 112 - leave * 112;
          const heroVisible = rise > 0 && leave < 1 && (last || frame < r0);
          // The last title travels into its column while its font size
          // shrinks. Layout rounds a baseline to whole pixels, so moving it by
          // `left`/`top`/`fontSize` clicks; while it travels it is laid out
          // where it lands and carried there by a transform. At rest it keeps
          // the plain layout.
          const travelling = last && resolve > 0 && resolve < 1;
          const heroDescOut = last
            ? interpolate(resolve, [0, 0.35], [1, 0], CLAMP)
            : interpolate(
                frame,
                [at(i + 1) - 10, at(i + 1) - 3],
                [1, 0],
                CLAMP,
              );

          return (
            <div key={it.title}>
              {heroVisible ? (
                <>
                  <div
                    style={{
                      position: "absolute",
                      left: travelling ? c.x : heroX,
                      top: travelling ? rowTitleY : heroYNow,
                      transform: travelling
                        ? `translate(${heroX - c.x}px, ${heroYNow - rowTitleY}px) translate(-50%, -50%) scale(${heroFsNow / rowFs})${glide(true)}`
                        : "translate(-50%, -50%)",
                      overflow: resolve > 0 && last ? "visible" : "hidden",
                      padding: travelling
                        ? `${rowFs * 0.08}px ${rowFs * 0.06}px ${rowFs * 0.14}px`
                        : `${heroFsNow * 0.08}px ${heroFsNow * 0.06}px ${heroFsNow * 0.14}px`,
                    }}
                  >
                    <div
                      style={{
                        ...titleStyle,
                        fontSize: travelling ? rowFs : heroFsNow,
                        transform: `translateY(${soloY}%)${glide(
                          !travelling && (midway(rise) || midway(leave)),
                        )}`,
                      }}
                    >
                      {it.title}
                    </div>
                  </div>
                  <div
                    style={{
                      position: "absolute",
                      left: width / 2 - width * 0.35,
                      width: width * 0.7,
                      top: heroDescTop,
                      textAlign: "center",
                      textWrap: "balance",
                      fontFamily: geist.fontFamily,
                      fontWeight: 400,
                      fontSize: heroDescFs,
                      lineHeight: 1.35,
                      letterSpacing: "-0.01em",
                      color: p.muted,
                      opacity: descIn * heroDescOut,
                      transform: `translateY(${(1 - descIn) * 12 * s - (1 - heroDescOut) * 10 * s}px)${glide(midway(descIn) || midway(heroDescOut))}`,
                      filter: `blur(${(1 - descIn) * 5 * s}px)`,
                    }}
                  >
                    {it.description}
                  </div>
                </>
              ) : null}

              {/* row copy for the earlier items */}
              {!last && back > 0 ? (
                <div
                  style={{
                    position: "absolute",
                    left: c.x,
                    top: rowTitleY,
                    transform: "translate(-50%, -50%)",
                    overflow: "hidden",
                    padding: `${rowFs * 0.08}px ${rowFs * 0.06}px ${rowFs * 0.14}px`,
                  }}
                >
                  <div
                    style={{
                      ...titleStyle,
                      fontSize: rowFs,
                      transform: `translateY(${(1 - back) * 112}%)${glide(midway(back))}`,
                    }}
                  >
                    {it.title}
                  </div>
                </div>
              ) : null}

              {/* row description */}
              {rowDescIn > 0 ? (
                <div
                  style={{
                    position: "absolute",
                    left: c.x - (portrait ? colW : c.w) / 2,
                    width: portrait ? colW : c.w,
                    top: rowDescTop,
                    textAlign: "center",
                    textWrap: "balance",
                    fontFamily: geist.fontFamily,
                    fontWeight: 400,
                    fontSize: rowDescFs,
                    lineHeight: 1.45,
                    letterSpacing: "-0.005em",
                    color: p.muted,
                    opacity: rowDescIn,
                    transform: `translateY(${(1 - rowDescIn) * 10 * s}px)${glide(midway(rowDescIn))}`,
                    filter: `blur(${(1 - rowDescIn) * 4 * s}px)`,
                  }}
                >
                  {it.description}
                </div>
              ) : null}
            </div>
          );
        })}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  hold: {
    type: "number",
    default: 36,
    min: 0,
    max: 90,
    step: 1,
    description: "Hold (frames)",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Bricolage Grotesque",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","hold","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  hold: 36,
  accent: "#3B5BFD",
  fontFamily: "Bricolage Grotesque",
  scale: 1,
  delay: 0,
  speed: 1,
};

type FeatureTrioElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FeatureTrioBase>;

const FeatureTrioInner = forwardRef<
  HTMLDivElement,
  FeatureTrioElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FeatureTrio>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FeatureTrioBase
          {...(componentProps as unknown as ComponentProps<typeof FeatureTrioBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FeatureTrio = Interactive.withSchema({
  Component: FeatureTrioInner,
  componentName: "<FeatureTrio>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
